import pandas as pd
import numpy as np

# Load all available experiments
files = {
    'exp1': experiment_1_csv,
    'exp3': experiment_3_csv, 
    'exp4': experiment_4_csv,
    'exp5': experiment_5_csv,
    'exp6': experiment_6_csv,
    'exp7': experiment_7_csv,
    'exp8': experiment_8_csv,
}

for name, fpath in files.items():
    try:
        df = pd.read_csv(fpath)
        print(f"\n=== {name} ===")
        print(f"Columns: {list(df.columns)}")
        print(f"Shape: {df.shape}")
        if 'CropYield' in df.columns:
            print(f"Yield mean: {df['CropYield'].mean():.2f}, std: {df['CropYield'].std():.2f}")
        # Show unique values for categorical-looking columns
        for col in df.columns:
            if df[col].dtype == 'object' or df[col].nunique() < 10:
                print(f"  {col}: {df[col].unique()}")
        # Show numeric correlations with yield if available
        if 'CropYield' in df.columns:
            num_cols = df.select_dtypes(include=[np.number]).columns
            if len(num_cols) > 1:
                corr = df[num_cols].corr(numeric_only=True)['CropYield'].drop('CropYield').sort_values(ascending=False)
                print(f"  Yield correlations: {corr.to_dict()}")
    except Exception as e:
        print(f"\n=== {name} === ERROR: {e}")
